-- Create "cms_page_translations" table
CREATE TABLE "cms"."cms_page_translations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "deleted_at" timestamptz NULL, "status" character varying NOT NULL DEFAULT 'DRAFT', "publish_at" timestamptz NULL, "locale" character varying NOT NULL, "title" character varying NOT NULL, "slug" character varying NOT NULL, "body" text NOT NULL DEFAULT '', "page_id" bigint NOT NULL, "workspace_id" bigint NOT NULL, "created_by" bigint NOT NULL, "updated_by" bigint NOT NULL, "deleted_by_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "cms_page_translations_cms_pages_translations" FOREIGN KEY ("page_id") REFERENCES "cms"."cms_pages" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "cms_page_translations_users_creator" FOREIGN KEY ("created_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "cms_page_translations_users_deleter" FOREIGN KEY ("deleted_by_id") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "cms_page_translations_users_updater" FOREIGN KEY ("updated_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "cms_page_translations_workspaces_workspace" FOREIGN KEY ("workspace_id") REFERENCES "core"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "cmspagetranslation_page_id_locale" to table: "cms_page_translations"
CREATE UNIQUE INDEX "cmspagetranslation_page_id_locale" ON "cms"."cms_page_translations" ("page_id", "locale") WHERE (deleted_at IS NULL);
-- Create index "cmspagetranslation_workspace_id_deleted_at" to table: "cms_page_translations"
CREATE INDEX "cmspagetranslation_workspace_id_deleted_at" ON "cms"."cms_page_translations" ("workspace_id", "deleted_at");
-- Create index "cmspagetranslation_workspace_id_locale_slug" to table: "cms_page_translations"
CREATE UNIQUE INDEX "cmspagetranslation_workspace_id_locale_slug" ON "cms"."cms_page_translations" ("workspace_id", "locale", "slug") WHERE (deleted_at IS NULL);
-- Create index "cmspagetranslation_workspace_id_locale_status_publish_at" to table: "cms_page_translations"
CREATE INDEX "cmspagetranslation_workspace_id_locale_status_publish_at" ON "cms"."cms_page_translations" ("workspace_id", "locale", "status", "publish_at");
-- Backfill existing cms_pages into cms_page_translations
INSERT INTO "cms"."cms_page_translations"
  ("page_id", "workspace_id", "locale", "title", "slug", "body", "status", "publish_at", "created_at", "updated_at", "created_by", "updated_by", "deleted_at")
SELECT
  "id", "workspace_id", 'en', "title", "slug", "body", "status", "publish_at", "created_at", "updated_at", "created_by", "updated_by", "deleted_at"
FROM "cms"."cms_pages";
-- Modify "cms_pages" table
ALTER TABLE "cms"."cms_pages" DROP COLUMN "status", DROP COLUMN "publish_at", DROP COLUMN "title", DROP COLUMN "slug", DROP COLUMN "body";
-- Create "cms_post_translations" table
CREATE TABLE "cms"."cms_post_translations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "deleted_at" timestamptz NULL, "status" character varying NOT NULL DEFAULT 'DRAFT', "publish_at" timestamptz NULL, "locale" character varying NOT NULL, "title" character varying NOT NULL, "slug" character varying NOT NULL, "excerpt" character varying NULL, "body" text NOT NULL DEFAULT '', "post_id" bigint NOT NULL, "workspace_id" bigint NOT NULL, "created_by" bigint NOT NULL, "updated_by" bigint NOT NULL, "deleted_by_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "cms_post_translations_cms_posts_translations" FOREIGN KEY ("post_id") REFERENCES "cms"."cms_posts" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "cms_post_translations_users_creator" FOREIGN KEY ("created_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "cms_post_translations_users_deleter" FOREIGN KEY ("deleted_by_id") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "cms_post_translations_users_updater" FOREIGN KEY ("updated_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "cms_post_translations_workspaces_workspace" FOREIGN KEY ("workspace_id") REFERENCES "core"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "cmsposttranslation_post_id_locale" to table: "cms_post_translations"
CREATE UNIQUE INDEX "cmsposttranslation_post_id_locale" ON "cms"."cms_post_translations" ("post_id", "locale") WHERE (deleted_at IS NULL);
-- Create index "cmsposttranslation_workspace_id_deleted_at" to table: "cms_post_translations"
CREATE INDEX "cmsposttranslation_workspace_id_deleted_at" ON "cms"."cms_post_translations" ("workspace_id", "deleted_at");
-- Create index "cmsposttranslation_workspace_id_locale_slug" to table: "cms_post_translations"
CREATE UNIQUE INDEX "cmsposttranslation_workspace_id_locale_slug" ON "cms"."cms_post_translations" ("workspace_id", "locale", "slug") WHERE (deleted_at IS NULL);
-- Create index "cmsposttranslation_workspace_id_locale_status_publish_at" to table: "cms_post_translations"
CREATE INDEX "cmsposttranslation_workspace_id_locale_status_publish_at" ON "cms"."cms_post_translations" ("workspace_id", "locale", "status", "publish_at");
-- Backfill existing cms_posts into cms_post_translations
INSERT INTO "cms"."cms_post_translations"
  ("post_id", "workspace_id", "locale", "title", "slug", "excerpt", "body", "status", "publish_at", "created_at", "updated_at", "created_by", "updated_by", "deleted_at")
SELECT
  "id", "workspace_id", 'en', "title", "slug", "excerpt", "body", "status", "publish_at", "created_at", "updated_at", "created_by", "updated_by", "deleted_at"
FROM "cms"."cms_posts";
-- Modify "cms_posts" table
ALTER TABLE "cms"."cms_posts" DROP COLUMN "status", DROP COLUMN "publish_at", DROP COLUMN "title", DROP COLUMN "slug", DROP COLUMN "excerpt", DROP COLUMN "body";
-- Create "cms_settings" table
CREATE TABLE "cms"."cms_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "default_locale" character varying NOT NULL DEFAULT 'en', "supported_locales" jsonb NOT NULL, "workspace_id" bigint NOT NULL, "created_by" bigint NOT NULL, "updated_by" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "cms_settings_users_creator" FOREIGN KEY ("created_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "cms_settings_users_updater" FOREIGN KEY ("updated_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "cms_settings_workspaces_workspace" FOREIGN KEY ("workspace_id") REFERENCES "core"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "cmssetting_workspace_id" to table: "cms_settings"
CREATE UNIQUE INDEX "cmssetting_workspace_id" ON "cms"."cms_settings" ("workspace_id");
-- Backfill existing workspaces into cms_settings
INSERT INTO "cms"."cms_settings" ("workspace_id", "default_locale", "supported_locales", "created_at", "updated_at", "created_by", "updated_by")
SELECT "id", 'en', '["en", "id"]'::jsonb, NOW(), NOW(), "owner_id", "owner_id"
FROM "core"."workspaces"
ON CONFLICT DO NOTHING;
